<script setup lang="ts">
import { computed, ref } from 'vue'
import { useAuthStore } from '../../stores/auth'
import { formatTime } from '../time'
import ApprovalActions from './ApprovalActions.vue'
import { RISK_LABELS, STATUS_LABELS, type Execution } from './queries'

// One tool call. The summary is generated by the workspace from the stored arguments (never the AI's own text);
// arguments are already masked by the server and shown as plain text.
const props = defineProps<{ scope: string; execution: Execution; focused?: boolean }>()
const auth = useAuthStore()
const open = ref(!!props.focused)
const pending = computed(() => props.execution.status === 'pending_approval')
const args = computed(() => JSON.stringify(props.execution.arguments, null, 2))
const source = computed(() => props.execution.source)
</script>

<template>
  <li class="panel ai-execution" :class="{ 'ai-execution-focused': focused }" :aria-current="focused ? 'true' : undefined">
    <div class="ai-heading">
      <h3 class="preserve-text">{{ execution.summary }}</h3>
      <span class="badge" :class="`ai-risk-${execution.risk_level}`">{{ RISK_LABELS[execution.risk_level] }}</span>
      <span class="badge" :class="`ai-status-${execution.status}`">{{ STATUS_LABELS[execution.status] }}</span>
    </div>
    <p class="form-help">
      实例 <strong>{{ execution.instance_name }}</strong> · 工具 <code>{{ execution.tool_name }}</code> · 发起于 <time :datetime="execution.created_at">{{ formatTime(execution.created_at) }}</time>
      <template v-if="pending && execution.expires_at"> · <time :datetime="execution.expires_at">{{ formatTime(execution.expires_at) }}</time> 前没人处理会自动拒绝</template>
    </p>
    <p v-if="source.conversation_id" class="form-help">
      <!-- The IM page is for owner / admin only; others just see where it came from. -->
      来源：<RouterLink v-if="auth.canManage" :to="{ path: '/im', query: { c: source.conversation_id } }">IM 会话</RouterLink><span v-else>IM 会话</span><template v-if="source.inferred">（根据实例最近收到的消息推断）</template>
    </p>
    <p v-if="execution.result_summary" class="preserve-text">结果：{{ execution.result_summary }}</p>
    <p v-if="execution.error_code" class="note-text">错误码：<code>{{ execution.error_code }}</code></p>
    <p v-if="execution.decision_reason" class="preserve-text">拒绝原因：{{ execution.decision_reason }}</p>
    <p v-if="execution.decided_at" class="form-help">处理于 <time :datetime="execution.decided_at">{{ formatTime(execution.decided_at) }}</time></p>
    <button type="button" class="secondary-button" :aria-expanded="open" @click="open = !open">{{ open ? '收起参数' : '查看参数' }}</button>
    <pre v-if="open" class="ai-arguments">{{ args }}</pre>
    <ApprovalActions v-if="pending && auth.canManage" :scope="scope" :execution="execution" />
    <p v-else-if="pending" class="form-help">等待 owner 或 admin 审批。</p>
  </li>
</template>
